const { DataTypes } = require("sequelize");
const sequelize = require("../config/database");

const Device = sequelize.define(
  "Device",
  {
    id: {
      type: DataTypes.UUID,
      defaultValue: DataTypes.UUIDV4,
      primaryKey: true,
    },
    // Null until an admin authorizes the pairing code — a freshly
    // installed player app isn't tied to any organization yet.
    organizationId: {
      type: DataTypes.UUID,
      allowNull: true,
    },

    // Identity
    deviceId: {
      // Generated by the player app itself on first install (e.g. a UUID
      // it creates and stores locally) — NOT the same as this row's `id`.
      type: DataTypes.STRING,
      allowNull: false,
      unique: true,
    },
    deviceTokenHash: {
      type: DataTypes.STRING,
      allowNull: true,
    },
    // Raw token, held only briefly between admin authorization and the
    // device's next pairing-status poll, then cleared.
    pendingDeviceToken: {
      type: DataTypes.STRING,
      allowNull: true,
    },
    pairingCode: {
      type: DataTypes.STRING,
      allowNull: true,
    },
    pairingCodeExpiresAt: {
      type: DataTypes.DATE,
      allowNull: true,
    },
    status: {
      type: DataTypes.ENUM("pending", "authorized", "revoked"),
      defaultValue: "pending",
    },

    // Display properties (PRD Section 6.F)
    displayName: DataTypes.STRING,
    serialNumber: DataTypes.STRING,
    location: DataTypes.STRING,
    latitude: DataTypes.FLOAT,
    longitude: DataTypes.FLOAT,
    resolution: DataTypes.STRING,
    groupId: {
      type: DataTypes.UUID,
      allowNull: true,
    },

    // Runtime / diagnostics (PRD Section 7)
    platform: {
      type: DataTypes.ENUM("android", "windows"),
      allowNull: false,
    },
    appVersion: DataTypes.STRING,
    osVersion: DataTypes.STRING,
    ipAddress: DataTypes.STRING,
    lastHeartbeatAt: DataTypes.DATE,
    storageUsedMB: DataTypes.FLOAT,
    storageTotalMB: DataTypes.FLOAT,
    temperatureC: DataTypes.FLOAT,
    ramUsagePercent: DataTypes.FLOAT,
    cpuUsagePercent: DataTypes.FLOAT,
    currentContentId: DataTypes.STRING,

    lastScreenshotUrl: DataTypes.STRING,
    lastScreenshotAt: DataTypes.DATE,

     // PRD Section 6.I — feedback overlay can be toggled per-display
    feedbackEnabled: {
      type: DataTypes.BOOLEAN,
      defaultValue: false,
    },
  },
  {
    tableName: "devices",
    timestamps: true,
  },
);

module.exports = Device;
